/**
 * Signed attestation fixtures for the PHP gate test.
 *
 * Generated by nostr-tools and verified by the node's own pure-PHP BIP-340
 * implementation — the same cross-language check the event tests use. A gate
 * that only agrees with the library that produced its inputs proves nothing.
 */
import { finalizeEvent, generateSecretKey, getPublicKey } from 'nostr-tools';
import { sha256 } from '@noble/hashes/sha2.js';
import { bytesToHex } from '@noble/hashes/utils.js';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const ORIGIN = 'https://signer.xonly.ai';
const PATH = '/dist/signer.js';

const releaseKey = generateSecretKey();
const releasePub = getPublicKey(releaseKey);
const attackerKey = generateSecretKey();
const attackerPub = getPublicKey(attackerKey);

const GOOD = '/* signer v2.4.1 — the real thing */';
const EVIL = '/* signer v2.4.1 — exfiltrates prf_out */';
const h = (s) => bytesToHex(sha256(new TextEncoder().encode(s)));

const now = Math.floor(Date.now() / 1000);

const att = (sha, key, at, origin = ORIGIN, version = '2.4.1') =>
  finalizeEvent({
    kind: 30078,
    created_at: at,
    tags: [
      ['d', 'berm:signer-build:v1'],
      ['origin', origin],
      ['version', version],
      ['sha256', sha],
      ['path', PATH],
    ],
    content: '',
  }, key);

writeFileSync(join(HERE, 'gate-fixtures.json'), JSON.stringify({
  origin: ORIGIN,
  path: PATH,
  releasePub,
  attackerPub,
  goodBody: GOOD,
  evilBody: EVIL,
  goodHash: h(GOOD),
  evilHash: h(EVIL),
  genuine: att(h(GOOD), releaseKey, now - 100),
  forgedNewer: att(h(EVIL), attackerKey, now - 1),
  wrongOrigin: att(h(GOOD), releaseKey, now - 100, 'https://signer.evil.tld'),
  stale: att(h(GOOD), releaseKey, now - 60 * 86400),
}, null, 2));

console.log('wrote gate-fixtures.json');
console.log('  release pub :', releasePub.slice(0, 16) + '…');
console.log('  good hash   :', h(GOOD).slice(0, 16) + '…');
console.log('  evil hash   :', h(EVIL).slice(0, 16) + '…');
